/* MAL discovery has an in-memory lifetime. Only explicit Add writes to the library. */
const Discover=(()=>{
 const A=DiscoverAPI,CLIENT='anishelf-mal-client-id',SESSION='anishelf-mal-session',ENABLED='anishelf-discover-enabled';
 const say=(zh,en)=>I18n.getLanguage()==='en-US'?en:zh;
 let clientId='',session='',enabled=true,connected=false,accountError='',epoch=0,controller=null,pollTimer=null,pollUntil=0;
 let columns={ranking:{rows:[],state:'idle',error:''},season:{rows:[],state:'idle',error:''},suggestions:{rows:[],state:'idle',error:''}},activePreview=null,previewVersion=0;
 const records=new Map(),tmdbCache=new Map();let queue=[],running=0;
 try{clientId=localStorage.getItem(CLIENT)||'';session=localStorage.getItem(SESSION)||'';enabled=localStorage.getItem(ENABLED)!=='false'}catch{}
 const request=(route,input={})=>A.request(route,{clientId,session,...input},{signal:controller?.signal});
 function forget(){epoch++;controller?.abort();controller=new AbortController();queue=[];records.clear();tmdbCache.clear();activePreview=null;previewVersion++;for(const c of Object.values(columns)){c.rows=[];c.state='idle';c.error=''}}
 function supported(){return location.origin==='http://127.0.0.1:43871'}
 function sync(){const button=$('#discoverNav');if(button){button.hidden=!enabled;button.setAttribute('aria-label',say('发现','Discover'));button.title=say('发现','Discover')}if(!enabled&&page==='discover')page='library';}
 function settingStatus(){const n=$('#malConnectionStatus');if(n)n.textContent=connected?say('MAL 账号已连接','MAL account connected'):accountError||say('未连接账号；总榜和新作可仅凭 Client ID 使用。','Account not connected. Client ID alone supports rankings and this season.');const b=$('#malAuthorize');if(b)b.disabled=!clientId||!supported();}
 async function accountStatus(){const identity=clientId+':'+session,stamp=epoch;if(!clientId||!session){connected=false;settingStatus();return}try{const data=await request('auth/status');if(identity!==clientId+':'+session||stamp!==epoch)return;connected=data.connected===true;accountError=data.error||'';if(!connected&&!data.pending){session='';try{localStorage.removeItem(SESSION)}catch{}}}catch(error){if(identity!==clientId+':'+session||stamp!==epoch)return;connected=false;accountError=error.message}settingStatus()}
 async function authorize(){
  // Open synchronously from the click, before the async OAuth preparation, to avoid popup blocking.
  const popup=window.open('about:blank','anishelf-mal-auth','popup,width=760,height=820');if(!popup){accountError=say('请允许本应用打开授权窗口。','Allow AniShelf to open the authorization window.');settingStatus();return}
  try{popup.opener=null;const data=await request('auth/start');const target=new URL(data.url);if(target.origin!=='https://myanimelist.net'||target.pathname!=='/v1/oauth2/authorize'||!/^[a-f0-9]{64}$/.test(data.session))throw Error('Invalid authorization response');session=data.session;try{localStorage.setItem(SESSION,session)}catch{}connected=false;accountError='';popup.location.replace(data.url);pollUntil=Date.now()+10*60*1000;clearTimeout(pollTimer);
   const poll=async()=>{if(!enabled||Date.now()>pollUntil)return;await accountStatus();if(!enabled)return;if(connected){columns.suggestions={rows:[],state:'idle',error:''};if(page==='discover')loadColumn('suggestions');return}if(session&&!accountError&&Date.now()<pollUntil)pollTimer=setTimeout(poll,2000)};poll();
  }catch(error){popup.close();accountError=error.message;settingStatus()}
 }
 function settings(){const section=document.createElement('section');section.className='discover-settings';
  section.innerHTML='<h3>'+say('Discover 设置','Discover settings')+'</h3><label class="discover-switch"><input type="checkbox" id="discoverEnabled"'+(enabled?' checked':'')+'>'+say('显示 Discover','Show Discover')+'</label><label for="malClientId">MAL Client ID<input id="malClientId" type="text" maxlength="128" autocomplete="off" spellcheck="false"></label><div class="discover-settings-actions"><button id="saveMalClient">'+say('绑定 Client ID','Bind Client ID')+'</button><button id="malAuthorize">'+say('连接 MAL 账号','Connect MAL account')+'</button><button id="malDisconnect">'+say('断开账号','Disconnect account')+'</button><a href="https://myanimelist.net/apiconfig" target="_blank" rel="noopener noreferrer">'+say('注册 MAL 应用','Register MAL application')+' ↗</a></div><p id="malConnectionStatus" role="status"></p><p>'+say('请注册无需 Client Secret 的公共／原生客户端，并将回调地址设置为：','Register a public/native client that does not require a Client Secret. Set its redirect URI to:')+'</p><code class="discover-callback">http://127.0.0.1:43871/.anishelf/mal/callback</code><p>'+say('只读取 MAL 推荐，不同步或上传 AniShelf 收藏、评分、备注和观看记录。Client ID 和连接标识仅保存在此浏览器；令牌只在本地服务内存中，服务重启后需要重新连接。Discover 浏览数据不进入资料夹或备份。','Reads MAL recommendations without uploading or syncing AniShelf library, ratings, notes or viewing history. Client ID and connection handle stay in this browser; tokens stay in local-service memory and reconnect after service restart. Discovery data is excluded from folders and backups.')+'</p>';
  $('#extraSection .settings-panel').append(section);$('#malClientId').value=clientId;
  $('#discoverEnabled').onchange=e=>{const next=e.target.checked;try{localStorage.setItem(ENABLED,String(next))}catch{e.target.checked=enabled;toast(say('无法保存设置','Could not save settings'));return}enabled=next;if(!enabled){forget();clearTimeout(pollTimer);if(String(selectedId).startsWith('discover:'))closeDetailPanel()}sync();};
  $('#saveMalClient').onclick=()=>{const next=$('#malClientId').value.trim();if(next&&!/^[a-zA-Z0-9_-]{8,128}$/.test(next)){accountError=say('请输入有效的 MAL Client ID。','Enter a valid MAL Client ID.');settingStatus();return}try{localStorage.setItem(CLIENT,next);if(next!==clientId){localStorage.removeItem(SESSION);session='';connected=false;clearTimeout(pollTimer);forget()}clientId=next;accountError='';settingStatus();toast(say('Client ID 已保存','Client ID saved'))}catch{toast(say('无法保存设置','Could not save settings'))}};
  $('#malAuthorize').onclick=authorize;$('#malDisconnect').onclick=async()=>{try{if(session)await request('auth/disconnect');session='';connected=false;localStorage.removeItem(SESSION);clearTimeout(pollTimer);forget();accountError='';settingStatus()}catch(error){accountError=error.message;settingStatus()}};settingStatus();
 }
 const columnNames={ranking:['总榜 · 前 10','Top 10'],season:['本季新作 · 10 部','This season · 10'],suggestions:['个性化推荐','For you']};
 function card(a,index){const r=records.get(a.malId),q=$('#search').value.trim().toLowerCase();if(q&&!((a.title+' '+a.romanTitle).toLowerCase().includes(q)))return '';
  return '<article class="anime-card discover-card"><button class="poster" data-discover-id="'+a.malId+'" aria-label="'+esc(say('查看 ','View ')+a.title)+'"><img src="'+esc(safeImage(r?.candidate?.image||r?.base?.image||''))+'" alt="'+esc(a.title)+'" loading="lazy" decoding="async"><span class="discover-rank">'+(index+1)+'</span></button><div class="card-text"><h3>'+esc(a.title)+'</h3><div class="card-meta"><span>'+esc(a.year||'—')+'</span><span class="rating">'+(a.score===null?'':'MAL '+a.score.toFixed(1))+'</span></div><p class="discover-match-state">'+esc(r?.state==='ready'?say('TMDb 资料','TMDb metadata'):r?.state==='ambiguous'?say('需确认 TMDb 匹配','Confirm TMDb match'):r?.state==='failed'?say('资料加载失败','Metadata unavailable'):tmdbCredential?say('正在匹配 TMDb…','Matching TMDb…'):say('需要 TMDb 凭据','TMDb configuration needed'))+'</p></div></article>';
 }
 function paintColumn(kind){if(page!=='discover')return;const node=$('#discover-'+kind);if(!node)return;const c=columns[kind];
  node.innerHTML=c.state==='loading'?'<p class="detail-empty" role="status">'+say('加载中…','Loading…')+'</p>':c.state==='error'?'<p class="detail-empty" role="status">'+esc(c.error)+'</p><button data-discover-retry="'+kind+'">'+say('重试','Retry')+'</button>':c.rows.length?'<div class="discover-cards">'+c.rows.map(card).join('')+'</div>':'<p class="detail-empty">'+(kind==='suggestions'?say('连接 MAL 账号后获取官方推荐；新账号可能暂无推荐。','Connect your MAL account for official recommendations. New accounts may have no suggestions.'):say('暂无结果','No results'))+'</p>';
  node.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.onerror=null;img.src=placeholder});
 }
 function renderPage(){sync();if(!enabled)return;$('#librarySection').hidden=true;$('#extraSection').hidden=false;$('.section-toolbar').hidden=true;
  $('#extraSection').innerHTML='<section class="discover-page"><div class="discover-heading"><p>'+say('MAL 榜单与推荐 · TMDb 海报和资料','MAL rankings and recommendations · TMDb artwork and metadata')+'</p><button id="refreshDiscover">'+say('刷新','Refresh')+'</button></div>'+(!supported()?'<p class="detail-empty">'+say('请通过新版一键启动器打开 AniShelf。','Open AniShelf using the updated local launcher.')+'</p>':!clientId?'<p class="detail-empty">'+say('请先在设置中绑定 MAL Client ID。','Bind a MAL Client ID in Settings first.')+'</p>':'')+'<div class="discover-columns">'+Object.entries(columnNames).map(([kind,label])=>'<section class="discover-column" aria-labelledby="discover-title-'+kind+'"><h2 id="discover-title-'+kind+'">'+label[I18n.getLanguage()==='en-US'?1:0]+'</h2><div id="discover-'+kind+'"></div></section>').join('')+'</div><p class="discover-attribution">'+say('排名及推荐来自 MyAnimeList。浏览不会添加收藏或创建观看记录。','Rankings and recommendations from MyAnimeList. Browsing does not add library entries or viewing records.')+'</p></section>';
  for(const key of Object.keys(columns))paintColumn(key);$('#refreshDiscover').onclick=()=>{forget();render();};
  if(supported()&&clientId)for(const key of Object.keys(columns))if(columns[key].state==='idle')loadColumn(key);
 }
 async function loadColumn(kind){if(!enabled||!clientId||!supported()||columns[kind].state==='loading')return;const stamp=epoch,c=columns[kind];c.state='loading';c.error='';paintColumn(kind);
  try{if(kind==='suggestions'){await accountStatus();if(!connected){c.state='ready';c.rows=[];paintColumn(kind);return}}
   const data=await request('request',{kind,...(kind==='season'?A.season():{})});if(stamp!==epoch||!enabled)return;c.rows=A.rows(data);c.state='ready';
   for(const a of c.rows){if(!records.has(a.malId)){records.set(a.malId,{anime:a,state:'idle',base:null,candidate:null,choices:[],error:''});if(tmdbCredential)queue.push({id:a.malId,stamp})}}paintColumn(kind);pump();
  }catch(error){if(stamp!==epoch)return;c.state='error';c.error=error.message;paintColumn(kind)}
 }
 function repaint(id){if(page==='discover')for(const key of Object.keys(columns))paintColumn(key);if(activePreview&&(!id||activePreview===id)&&selectedId==='discover:'+activePreview&&$('#detailDialog').open)paintPreview()}
 async function tmdb(path,params={}){const key=JSON.stringify([path,params]);if(tmdbCache.has(key))return tmdbCache.get(key);const task=TMDB.request(path,tmdbCredential,{language:'en-US',...params});tmdbCache.set(key,task);try{const result=await task;while(tmdbCache.size>80)tmdbCache.delete(tmdbCache.keys().next().value);return result}catch(error){if(tmdbCache.get(key)===task)tmdbCache.delete(key);throw error}}
 async function prepare(r,choice,stamp=epoch){const ticket=(r.matchRequest||0)+1;r.matchRequest=ticket;const a=r.anime,type=r.searchType||a.mediaType;const data=await tmdb(type+'/'+choice.id,{append_to_response:type==='movie'?'images,credits':'images,aggregate_credits',include_image_language:'en,null'});if(stamp!==epoch||r.matchRequest!==ticket)return;
  const base=TMDB.normalize(data,type);base.seriesTitle=data.name||a.title;base.title=a.title.slice(0,100);base.en=a.romanTitle;base.malId=a.malId;base.rating=0;base.note='';r.base=base;r.tmdbType=type;r.candidate=null;r.chosenSeason=null;
  if(type==='movie'){r.candidate={...base,entryType:'movie'};r.state='ready'}else{const s=A.chooseSeason(a,base.seasons||[]);if(s)await setSeason(r,s.number,stamp);else r.state='ambiguous'}
  if(stamp===epoch){if(r.candidate)DataSafety.validateCatalog([r.candidate]);repaint(r.anime.malId)}
 }
 async function setSeason(r,number,stamp=epoch){const base=r.base,ticket=(r.seasonRequest||0)+1;r.seasonRequest=ticket;const s=base?.seasons?.find(s=>s.number===number);if(!s)return;const data=await tmdb('tv/'+base.tmdbId+'/season/'+number,{append_to_response:'aggregate_credits'});if(stamp!==epoch||r.base!==base||r.seasonRequest!==ticket)return;const a=SeasonModel.from(base,s,data);a.title=r.anime.title.slice(0,100);a.en=r.anime.romanTitle;a.malId=r.anime.malId;a.metadataLanguage='en-US';a.rating=0;a.note='';DataSafety.validateCatalog([a]);r.candidate=a;r.chosenSeason=number;r.state='ready'}
 async function enrich(r,stamp){const ticket=(r.lookupRequest||0)+1;r.lookupRequest=ticket;r.state='loading';try{let data=await tmdb('search/'+r.anime.mediaType,{query:r.anime.title,include_adult:false,page:1});if(stamp!==epoch||r.lookupRequest!==ticket)return;let choices=(data.results||[]).filter(c=>!c.adult&&c.genre_ids?.includes(16)),match=A.chooseMatch(r.anime,choices);
   if(!match&&r.anime.romanTitle&&r.anime.romanTitle!==r.anime.title){data=await tmdb('search/'+r.anime.mediaType,{query:r.anime.romanTitle,include_adult:false,page:1});if(stamp!==epoch||r.lookupRequest!==ticket)return;choices=[...new Map([...choices,...(data.results||[]).filter(c=>!c.adult&&c.genre_ids?.includes(16))].map(c=>[c.id,c])).values()];match=A.chooseMatch(r.anime,choices)}
   r.choices=choices.slice(0,5);if(match)await prepare(r,match,stamp);else r.state='ambiguous';
  }catch(error){if(stamp===epoch&&r.lookupRequest===ticket){r.state='failed';r.error=error.message}}if(stamp===epoch&&r.lookupRequest===ticket)repaint(r.anime.malId);
 }
 function pump(){while(running<2&&queue.length){const item=queue.shift(),r=records.get(item.id);if(item.stamp!==epoch||!r)continue;running++;enrich(r,item.stamp).finally(()=>{running--;pump()})}}
 function owned(r){const a=r.candidate;if(!a)return null;return SeasonModel.leaves(library).find(b=>a.tmdbType==='movie'?b.tmdbType==='movie'&&b.tmdbId===a.tmdbId:SeasonModel.isSeason(b)&&SeasonModel.identity(b)===SeasonModel.identity(a))||library.find(b=>!SeasonModel.isSeason(b)&&!SeasonModel.isMerged(b)&&b.tmdbId===a.tmdbId&&b.tmdbType===a.tmdbType)}
 function paintPreview(){const r=records.get(activePreview);if(!r)return;const a=r.candidate||r.base||{},mal=r.anime,canAdd=!!r.candidate&&!owned(r);
  $('#detailBody').innerHTML='<div class="detail-cover">'+(a.heroImage||a.image?'<img class="detail-cover-art" src="'+esc(safeImage(a.heroImage||a.image))+'" alt="'+esc(mal.title)+'">':'<div class="detail-cover-placeholder"></div>')+'<div class="detail-cover-fade"></div><div class="detail-title-area"><h2 class="detail-title-fallback">'+esc(mal.title)+'</h2><p class="detail-air-meta">'+esc(mal.startDate||mal.year||'—')+'</p><p class="detail-genres">'+esc(a.genre||'')+'</p></div></div><div class="detail-content discover-detail"><div class="discover-preview-source"><a href="https://myanimelist.net/anime/'+mal.malId+'" target="_blank" rel="noopener noreferrer">MyAnimeList ↗</a></div><section class="detail-section"><h3>'+say('观看追踪','Watch Tracking')+'</h3><button class="primary" id="addDiscoverToLibrary"'+(canAdd?'':' disabled')+'>'+say('加入我的收藏','Add to My Library')+'</button>'+(owned(r)?'<p>'+say('已在资料库中','Already in My Library')+'</p>':'')+'</section><p id="discoverPreviewStatus" role="status">'+esc(r.error||(r.state==='loading'?say('正在加载 TMDb 资料…','Loading TMDb metadata…'):!tmdbCredential?say('请先在设置中配置 TMDb。','Configure TMDb in Settings first.'):''))+'</p>'+(!r.candidate||r.base?.tmdbType==='tv'?'<section class="detail-section"><h3>'+say('TMDb 匹配','TMDb match')+'</h3>'+(r.base?.tmdbType==='tv'?'<label>'+say('季度','Season')+'<select id="discoverSeason"><option value="">'+say('选择对应季度','Choose the matching season')+'</option>'+(r.base.seasons||[]).map(s=>'<option value="'+s.number+'"'+(r.chosenSeason===s.number?' selected':'')+'>'+esc(s.name||SeasonModel.label(s.number))+' · '+esc(s.airDate||'')+'</option>').join('')+'</select></label>':'')+(!r.candidate?'<form id="discoverMatchForm" class="discover-match-form"><label>'+say('搜索 TMDb','Search TMDb')+'<input id="discoverMatchQuery" maxlength="100" value="'+esc(mal.title.slice(0,100))+'" required></label><select id="discoverMatchType" aria-label="'+say('作品类型','Media type')+'"><option value="tv"'+((r.searchType||mal.mediaType)==='tv'?' selected':'')+'>'+say('剧集','TV')+'</option><option value="movie"'+((r.searchType||mal.mediaType)==='movie'?' selected':'')+'>'+say('电影','Movie')+'</option></select><button type="submit"'+(!tmdbCredential?' disabled':'')+'>'+say('搜索','Search')+'</button></form><div class="discover-match-choices">'+r.choices.map((c,i)=>'<button data-discover-match="'+i+'">'+esc(c.name||c.title)+' · '+esc((c.first_air_date||c.release_date||'').slice(0,4))+'</button>').join('')+'</div><button id="retryDiscoverMetadata"'+(!tmdbCredential?' disabled':'')+'>'+say('重新匹配','Retry match')+'</button>':'')+'</section>':'')+detailSection(say('概览','Overview'),'<p class="detail-overview">'+esc(a.overview||say('暂无已匹配的 TMDb 简介','No matched TMDb overview yet'))+'</p>')+(r.candidate?detailSection(say('主演','Cast'),personRail(a.cast))+detailSection(say('工作人员','Staff'),personRail(a.crew,true))+detailSection(say('每集简介','Episodes'),a.tmdbType==='movie'?say('电影无分集资料','Movies have no episode list'):episodeMarkup(a.episodeDetails?.[a.seasonNumber]||[])):'')+'</div>';
  $('#addDiscoverToLibrary').onclick=()=>add(activePreview);
  const form=$('#discoverMatchForm');if(form)form.onsubmit=async e=>{e.preventDefault();const query=$('#discoverMatchQuery').value.trim(),type=$('#discoverMatchType').value;if(!query||!['tv','movie'].includes(type)||!tmdbCredential)return;const stamp=epoch,ticket=(r.lookupRequest||0)+1;r.lookupRequest=ticket;try{const data=await tmdb('search/'+type,{query,include_adult:false,page:1});if(stamp!==epoch||r.lookupRequest!==ticket)return;r.searchType=type;r.choices=(data.results||[]).filter(c=>!c.adult&&c.genre_ids?.includes(16)).slice(0,5);r.error=r.choices.length?'':say('没有匹配结果','No matching results');paintPreview()}catch(error){r.error=error.message;paintPreview()}};
  const select=$('#discoverSeason');if(select)select.onchange=async()=>{if(!select.value)return;const n=Number(select.value),version=++previewVersion;select.disabled=true;try{await setSeason(r,n);if(version===previewVersion)repaint(r.anime.malId)}catch(error){r.error=error.message;repaint(r.anime.malId)}};
  $$('[data-discover-match]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await prepare(r,r.choices[Number(b.dataset.discoverMatch)])}catch(error){r.error=error.message;repaint(r.anime.malId)}});
  const retry=$('#retryDiscoverMetadata');if(retry)retry.onclick=()=>enrich(r,epoch);
  $$('#detailBody img').forEach(img=>img.onerror=()=>{img.onerror=null;img.src=placeholder});
 }
 function open(id){const r=records.get(id);if(!r||!enabled)return;activePreview=id;previewVersion++;selectedId='discover:'+id;paintPreview();showDetailPanel();if(r.state==='idle'&&tmdbCredential)enrich(r,epoch)}
 function add(id){const r=records.get(id);if(!r?.candidate||owned(r))return;try{const a=structuredClone(r.candidate);if(a.tmdbType==='movie'){a.id=Date.now();while(findLibraryEntry(a.id))a.id++}a.progress=0;a.status='planned';a.rating=0;a.rewatchCount=0;a.note='';a.favorite=false;a.watchDays=[];a.watchDay=null;a.startDate='';a.finishDate='';const next=[a,...library];DataSafety.validateCatalog(next);SeasonModel.validateCatalog(next);AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;render();paintPreview();toast(say('已加入我的收藏','Added to My Library'))}catch(error){r.error=error.message;paintPreview()}}
 function start(){sync();const base=renderSettings;renderSettings=function(){base();settings()};document.addEventListener('click',e=>{const card=e.target.closest?.('[data-discover-id]');if(card){open(Number(card.dataset.discoverId));return}const retry=e.target.closest?.('[data-discover-retry]');if(retry){columns[retry.dataset.discoverRetry].state='idle';loadColumn(retry.dataset.discoverRetry)}});render()}
 return {start,sync,renderPage,settings,open,add,loadColumn,records,get enabled(){return enabled},get clientId(){return clientId}};
})();
Discover.start();
